import { createCn } from 'cn/engine'
import tables from './cn-tables'

/**
 * Tailwind class merger (clsx + tailwind-merge semantics) built from precompiled tables.
 *
 * The tables (`./cn-tables.js`, generated by `cn build --full --css src/index.css`) already know
 * the FleetGuard theme scales from src/index.css, so `text-body` is a font *size* (not dropped
 * when merged with `text-white`) and `shadow-card` a shadow size. Using them with `cn/engine`
 * instead of `createCn` from `cn/config` keeps the runtime table compiler and default config
 * (~70 KB) out of the bundle and off the load-time main thread. `--full` keeps every class
 * group, so the tables never go stale when components change — only when the theme does.
 */
export const cn = createCn(tables)
